"""Original editorial website story. All records and scenes are synthetic."""
def illustrated_home(l,c,link):
    def t(zh,en): return zh if l=='zh' else en
    def photo(name, eager=False):
        return f'<picture><source media="(max-width:650px)" srcset="assets/{name}-small.png"><img src="assets/{name}.png" width="1280" height="720" alt="" {"fetchpriority=high" if eager else "loading=lazy"}></picture>'
    def detail(title,body):return f'<details class="chapter-details"><summary>{title}</summary><p>{body}</p></details>'
    ai=t('AI 生成场景，非真实客户端截图','AI-generated scene, not a client screenshot')
    synthetic=t('合成资料示意，非运行截图','Synthetic material, not a running screenshot')
    mark='<img src="assets/brand-mark.png" width="44" height="44" alt="">'
    hero=f'''<section class="story-hero"><div class="story-lead"><p class="eyebrow">{t('个人资料与记忆系统','A PERSONAL LIBRARY, WITH MEMORY')}</p><h1>{t('生活里留下的，<br>在这里接得上。','Keep the moment.<br>Continue the thought.')}</h1><p>{t('用手机和手表留下声音，把笔记、文字与工具会话汇进自己的资料库。查得到原文，重要的记忆由你确认。','Capture sound on your phone or watch. Bring notes, text and tool sessions into your own library. Find the source. Decide what stays.')}</p><div class="actions">{link('',c['source'],'button primary')}<a class="button secondary" href="start.html">{c['build']} ↗</a></div><p class="story-stage">{t('开源开发版 · 尚无已签名安装包','Open-source development build · No signed installer yet')}</p></div><figure class="hero-world">{photo('desk-scene-v3',True)}<figcaption>{ai}</figcaption><div class="index-slip"><div>{mark}<span>{t('自己的资料索引','YOUR SOURCE INDEX')}</span></div><p><time>09:10</time><span>{t('原音','Original audio')}</span><i>↗</i></p><p><time>10:35</time><span>{t('文字笔记','Written note')}</span><i>↗</i></p><p><time>16:20</time><span>{t('工具会话','Tool session')}</span><i>↗</i></p><small>{synthetic}</small></div></figure></section>
    <nav class="story-map" aria-label="{t('页面章节','Page chapters')}"><span>TRACEBOOK</span><a href="#capture">01 {t('留下','Capture')}</a><a href="#schedule">02 {t('回顾','Revisit')}</a><a href="#sources">03 {t('汇集','Gather')}</a><a href="#tool-reading">04 {t('连接','Connect')}</a><a href="#memory">05 {t('确认','Confirm')}</a><a href="#ownership">06 {t('持有','Own')}</a></nav>'''
    capture=f'''<section class="story-chapter" id="capture"><div class="chapter-heading"><p class="eyebrow">01 / {t('留下一个片刻','CAPTURE A MOMENT')}</p><h2>{t('灵感经过，不用让它等。','An idea should not have to wait.')}</h2></div><figure class="tap-scene">{photo('tap-scene-v4')}<div class="tap-copy"><p>08:40 / {t('出门前，想到一句话','A THOUGHT BEFORE HEADING OUT')}</p><h3>{t('轻点两下','Tap twice')}</h3><span class="tap-dots" aria-hidden="true">• •</span><p>{t('手机背面，一个熟悉的动作。','A familiar gesture, on the back of your phone.')}</p></div><figcaption>{ai}</figcaption></figure><ol class="capture-chain"><li><span>01</span>{t('轻点背面','Tap the back')}</li><li><span>02</span>{t('已绑定快捷指令','Your configured shortcut')}</li><li><span>03</span>{t('打开 App 录音','Open the app to record')}</li></ol><div class="audio-result"><span class="result-wave" aria-hidden="true">▂▅▃▆▂▇▄▃▆▂</span><b>00:42</b><span>{t('再次运行，停止并保存原音','Run again to stop and save the original audio')}</span><small>{synthetic}</small></div><p class="chapter-condition">{t('需系统绑定、解锁前台与麦克风授权；部分动作待真机验收。真实自动转写仍在开发。','Requires system binding, unlocked foreground access and microphone permission; some actions need real-device validation. Real automatic transcription is still in development.')}</p>
    {detail(t('查看入口条件','Capture entry conditions'),t('在系统中将“切换手机录音”快捷指令绑定到轻点背面两下。该动作打开 App，在前台开始或停止录音，不是任意后台免授权录音。声音先保存在本机；保存不等于转写已经完成。','Bind the phone recording shortcut to Back Tap in system settings. It opens the app to start or stop foreground recording, not unrestricted background capture. Sound is saved locally first; saving is not completed transcription.'))}
    <figure class="wrist-banner">{photo('walk-scene-v3')}<div><p>09:10 / {t('散步途中','ON A WALK')}</p><h3>{t('手机收起，<br>也能抬腕留下这一段。','Phone away.<br>Keep this moment on your wrist.')}</h3><span>≋ &nbsp; 00:42 / {t('原音来源示意','SYNTHETIC AUDIO SOURCE')}</span></div><figcaption>{ai}</figcaption></figure><p class="chapter-condition">{t('手表录音是另一入口；辅助触控捏合需另行绑定，不等于手机轻点背面。','Watch recording is a separate entry point. AssistiveTouch pinch requires its own setup; it is not phone Back Tap.')}</p></section>'''
    schedule=f'''<section class="story-chapter schedule-chapter" id="schedule"><div class="chapter-heading"><p class="eyebrow">02 / 07:30 · {t('次日，回到桌前','THE NEXT DAY, BACK AT YOUR DESK')}</p><h2>{t('给昨天，留一个回看的时间。','Make a little room for yesterday.')}</h2><p>{t('设好时间与时区。节点运行、到点检查时，回顾此前一天的笔记与录音资料，按来源汇集已有文字。','Choose a time and timezone. While the node is running, its scheduled check revisits the previous day’s notes and recordings, gathering available text with its sources.')}</p></div><div class="calendar-spread"><div class="calendar-time"><span>{t('计划时间示例','EXAMPLE SCHEDULE')}</span><strong>07:30</strong><div class="date-bridge"><b>10 / 22</b><span>↶</span><b>10 / 21</b></div><p>{t('今天，回看昨天。','Today, revisit yesterday.')}</p></div><div class="daily-paper"><div class="paper-heading"><b>{t('此前一天的资料','THE PREVIOUS DAY')}</b><small>{synthetic}</small></div><article><time>10:35</time><div><small>{t('文字笔记','WRITTEN NOTE')}</small><p>{t('演示先给出原文，再展示整理结果。','Show the original first, then the organized result.')}</p></div></article><article><time>16:20</time><div><small>{t('文字笔记','WRITTEN NOTE')}</small><p>{t('周四彩排，先检查引用是否能打开。','At Thursday’s rehearsal, check that citations open.')}</p></div></article><article><time>20:10</time><div><small>{t('已有录音文字 · 独立示例','EXISTING RECORDING TEXT · SEPARATE EXAMPLE')}</small><p>{t('这里需要再核对。','This needs another check.')}</p></div></article><p class="paper-note">{t('已有文字并非前章录音的自动转写结果。','This existing text is not an automatic transcript of the previous scene.')}</p></div></div><div class="analysis-option"><span class="static-toggle" aria-hidden="true"></span><div><b>{t('可选文字模型分析','Optional text-model analysis')}</b><p>{t('需自行配置并启用 · 仅笔记与已有录音文字 · 最近 7 天增量补分析 · 非定时录音','Configure and enable it yourself · Notes and available recording text only · Seven-day incremental analysis · Not scheduled recording')}</p></div></div>{detail(t('运行与模型条件','Runtime and model conditions'),t('节点运行时检查计划，不承诺设备关闭时自动工作。可选分析会把相应文字发给所选模型，服务可能收费；真实模型质量尚未验收。模型分析不自动确认长期记忆，也不表示所有资料类型都已自动整理。','The node checks its schedule while running; this is not a promise of execution on a powered-off device. Optional analysis sends relevant text to your selected model and may incur fees. Real-model quality is not yet validated. Analysis does not confirm long-term memories or automatically organize every source type.'))}</section>'''
    rows=[('10:35',t('演示思路','Presentation notes'),'note','v1'),('14:00',t('展示顺序.md','demo-outline.md'),'document','v1'),('15:10',t('讨论导出.json','discussion-export.json'),'note / chat','v1'),('16:20','Codex / Claude Code','input','v1')]
    sources=f'''<section class="story-chapter" id="sources"><div class="chapter-heading"><p class="eyebrow">03 / 16:20 · {t('回到做了一半的项目','RETURN TO A PROJECT IN PROGRESS')}</p><h2>{t('一段思考，常常不只在一个地方。','One thought. More than one place.')}</h2><p>{t('写下的笔记、已有文字、导出的聊天、已适配的工具会话，都可以留下自己的来源。','Notes, existing text, exported chats and adapted tool sessions can each keep their own source.')}</p></div><div class="source-workbench"><div class="incoming-strips"><span>≡ &nbsp; {t('笔记','Notes')}</span><span>▤ &nbsp; {t('文字文档.md','Text document.md')}</span><span>◌ &nbsp; {t('聊天导出.json','Chat export.json')}</span><span>⌘ &nbsp; Codex · Claude Code</span><p>{t('先预览，再确认导入','Preview before you import')} →</p></div><div class="source-index"><div class="paper-heading"><b>{t('秋季产品演示','AUTUMN PRODUCT DEMO')}</b><small>{t('导入示意 · 合成资料','IMPORT ILLUSTRATION · SYNTHETIC MATERIAL')}</small></div><div class="source-columns"><span>{t('可用时间','Available time')}</span><span>{t('名称','Name')}</span><span>{t('来源','Source')}</span><span>{t('版本','Version')}</span></div>{''.join(f'<div class="source-index-row"><time>{time}</time><b>{name}</b><span>{kind}</span><span>{version}</span></div>' for time,name,kind,version in rows)}<p class="paper-note">{t('保留可用时间与来源；未知时间明确标记。','Keep available timestamps and sources; mark unknown times clearly.')}</p></div></div><p class="chapter-condition">{t('支持已适配格式，不代表任意文档；导入不等于发给模型。','Adapted formats, not every document format. Importing does not mean sending to a model.')}</p>{detail(t('导入范围','Import formats'),t('UTF-8 .md、.markdown、.txt、.text 单份不超过 2 MB；已适配工具会话和聊天导出格式。PDF、Office 与扫描件尚未支持。聊天导入归笔记，保留可用时间与来源，未知时间明确标记。导入前预览确认，不自动将他人发言或助手回复当成你的事实。','UTF-8 .md, .markdown, .txt and .text up to 2 MB each, plus adapted tool sessions and chat exports. PDF, Office and scans are not supported yet. Chat imports become notes, retaining available timestamps and sources and marking unknown times. Preview and confirm imports; others’ statements and assistant replies do not automatically become facts about you.'))}</section>'''
    tools=f'''<section class="story-chapter tools-chapter" id="tool-reading"><div class="chapter-heading"><p class="eyebrow">04 / CLI · {t('接上同一条思考','CONTINUE THE SAME THREAD')}</p><h2>{t('换一个工具，也接得上上次的思考。','A different tool. The same thread.')}</h2><p>{t('让已授权的工具查找并读取资料，不用把每段背景重新讲一遍。','Let an authorized tool find and read your material, without starting the context over.')}</p></div><div class="access-directions"><span>{t('工具会话 → 迹库：归档','Tool sessions → Tracebook: archive')}</span><span>{t('迹库 → 已授权工具：只读查询','Tracebook → authorized tools: read-only lookup')}</span></div><div class="terminal-spread"><div class="terminal-panel"><div class="terminal-title"><span>● ● ●</span><small>{t('命令示例，非执行结果','COMMAND EXAMPLES, NOT EXECUTION OUTPUT')}</small></div><code><span>$</span> python3 integrations/lifto-library/scripts/lifto.py search "{t('产品演示','product demo')}" --scope notes<br><br><span>$</span> python3 integrations/lifto-library/scripts/lifto.py read note NOTE_ID</code><p>{t('在仓库根目录执行。NOTE_ID 替换为检索返回的真实编号。','Run from the repository root. Replace NOTE_ID with the actual identifier returned by search.')}</p></div><div class="retrieved-paper"><span class="eyebrow">{t('只读来源 · 合成示例','READ-ONLY SOURCE · SYNTHETIC EXAMPLE')}</span><h3>{t('演示思路','Presentation notes')}</h3><p>{t('“演示先给出原文，再展示整理结果。”','“Show the original first, then the organized result.”')}</p><small>NOTE_ID · note · v1</small><a href="#original-example">{t('核对这段合成原文','Check this synthetic source')} ↓</a></div></div><div class="original-reader" id="original-example" tabindex="-1"><div><span>{t('原文阅读 / 合成资料','ORIGINAL READER / SYNTHETIC MATERIAL')}</span><small>NOTE_ID · 10:35 · v1</small></div><p><span>01</span>{t('秋季产品演示 · 思路','Autumn product demo · Notes')}</p><p><span>02</span><mark>{t('演示先给出原文，再展示整理结果。','Show the original first, then the organized result.')}</mark></p><p><span>03</span>{t('让观众先看见依据，再解释整理过程。','Let the audience see the evidence before explaining the organization.')}</p></div><p class="chapter-condition">{t('只读：capabilities / search / query / read。资料检索不会生成模型回答。','Read-only: capabilities / search / query / read. Retrieval does not generate model answers.')}</p>{detail(t('授权与能力边界','Authorization and capabilities'),t('先配置 LIFTO_URL 与指向私密文件的 LIFTO_TOKEN_FILE，使用独立范围凭证，不把凭证写在命令或网页中。CLI 不能录音、改文件、确认记忆或更改设置；query 也不是模型问答。','Configure LIFTO_URL and LIFTO_TOKEN_FILE pointing to a private file, using independently scoped credentials. Do not put secrets in commands or pages. The CLI cannot record, edit files, confirm memory or change settings; query is not model Q&A.'))}</section>'''

    memory=f'''<section class="story-chapter" id="memory"><div class="chapter-heading"><p class="eyebrow">05 / {t('后来，留下值得继续用的部分','LATER, KEEP WHAT IS WORTH USING AGAIN')}</p><h2>{t('记住哪一部分，决定权在你。','You decide what deserves to stay.')}</h2><p>{t('从原文提出候选，由你确认。想法变了，就修订；不再适用，就停用。','Propose a candidate from the source. Confirm it yourself. Revise it when things change, or deactivate it when it no longer applies.')}</p></div><div class="memory-dossier"><div class="dossier-source"><span>{t('原文依据','SOURCE EVIDENCE')}</span><p>{t('“演示先给出原文，再展示整理结果。”','“Show the original first, then the organized result.”')}</p><small>note / NOTE_ID / v1</small></div><div class="dossier-main"><span class="eyebrow">{t('手动提出的候选','A MANUALLY PROPOSED CANDIDATE')}</span><h3>{t('秋季产品演示：<br>先展示原文，<br>再展示整理结果。','Autumn product demo:<br>show the original,<br>then the organized result.')}</h3><small>{synthetic}</small></div><div class="dossier-status"><span>{t('手动候选','MANUAL CANDIDATE')}</span><i>↓</i><strong>{t('本人确认','YOUR CONFIRMATION')}</strong><hr><b>✓ {t('已确认 · v1','CONFIRMED · v1')}</b><p>{t('保留原文片段','Original excerpt retained')}</p></div></div><details class="revision-example"><summary>{t('展开一次修订示例','See a revision example')} <span>v1 → v2</span></summary><div><p class="eyebrow">{t('另一条合成笔记','ANOTHER SYNTHETIC NOTE')}</p><p>{t('“内部草稿可以先列结论。”','“An internal draft can lead with conclusions.”')}</p><h3>{t('对外演示先给原文；<br>内部草稿可先列结论。','For external demos, show the original first.<br>For internal drafts, conclusions may come first.')}</h3><div class="revision-track"><span>{t('v1 保留','v1 RETAINED')}</span><i>→</i><b>{t('v2 当前','v2 CURRENT')}</b><span>{t('可停用 / 可恢复','DEACTIVATE / RESTORE')}</span></div></div></details><p class="chapter-condition">{t('手动候选、确认与修订已实现；自动模型整理仍在开发。此处是网页修订示意，不会写入客户端。','Manual candidates, confirmation and revision exist; automated model organization remains in development. This is a website illustration, not a write to the client.')}</p></section>'''
    ownership=f'''<section class="story-chapter ownership-chapter" id="ownership"><div class="chapter-heading"><p class="eyebrow">06 / {t('持有自己的资料','OWN YOUR MATERIAL')}</p><h2>{t('资料不该只存在于一个回答里。','Your material belongs beyond a single answer.')}</h2><p>{t('保留来源、内容版本与人工修改。你选择资料夹，文字也能带走。','Keep sources, content versions and your edits. Choose your folder. Take your text with you.')}</p></div><div class="ownership-spread"><div class="file-folder" aria-hidden="true"><span class="folder-sheet">≡<i></i><i></i></span><span class="folder-face">{mark}<b>Tracebook</b></span></div><div class="owned-files"><p class="eyebrow">{t('资料内容示意，不是实际目录结构','CONTENT ILLUSTRATION, NOT AN EXACT DIRECTORY TREE')}</p><div><span>01</span><b>{t('原始文字','Original text')}</b><small>{t('来源可回看','Return to the source')}</small></div><div><span>02</span><b>{t('记忆文字与依据','Memory text and evidence')}</b><small>{t('由你确认','Confirmed by you')}</small></div><div><span>03</span><b>{t('内容历史','Content history')}</b><small>{t('保留修改','Keep your edits')}</small></div></div></div><div class="export-strip"><b>{t('便携文字导出','Portable text export')}</b><span>✓ {t('文字','Text')}</span><span>− {t('不包含原音','No original audio')}</span><span>− {t('不包含凭证','No credentials')}</span></div><p class="chapter-condition">{t('不是完整备份或自动恢复包。真实异地云同步与后台链路仍待验收。','This is not a full backup or automatic restore package. Real remote cloud sync and background workflows still need validation.')}</p><a class="text-link" href="privacy.html">{t('了解资料与隐私','Read about data and privacy')} ↗</a></section>'''
    ending=f'''<section class="story-ending"><div>{mark}<p class="eyebrow">OPEN SOURCE / MIT</p><h2>{t('从真实能做的开始，<br>一起往前。','Start with what is real.<br>Build what comes next.')}</h2><p>{t('三端源码公开 · 开发版 · 暂无安装包','Source for three native clients · Development build · No installer yet')}</p><div class="actions">{link('',c['source'],'button primary')}<a class="button secondary" href="start.html">{c['build']} ↗</a>{link('/blob/main/ROADMAP.md',c['roadmap'],'text-link')}</div></div><div class="ending-boundaries">{detail(t('现在的记录与导入','Capture and imports today'),t('手机与手表的录音、暂停、保存和回放已有。快捷入口需系统设置与相应权限，部分真机动作仍待验收。导入支持已适配文字、工具会话与聊天导出格式，不承诺任意文档。','Phone and watch recording, pause, save and playback exist. Shortcuts require system setup and permissions; some real-device actions need validation. Import supports adapted text, tool-session and chat-export formats, not arbitrary documents.'))}{detail(t('模型、隐私与费用','Models, privacy and fees'),t('模型由你配置并选择启用，处理时相关文字可能发送给所选服务，服务可能收费。网站不自建账号或收集表单；当前 ChatGPT Sites 预览需平台登录，平台可能保存访问日志。','You configure and choose whether to enable models. Relevant text may be sent to your chosen service, which may charge fees. This website has no self-built accounts or collection forms; the current ChatGPT Sites preview requires platform login and may have hosting access logs.'))}{detail(t('仍待完成的转写与同步','Transcription and sync still in progress'),t('真实自动转写与自动模型记忆整理仍在开发。真实模型质量、异地云盘与后台链路仍待真实验收。资料对话目前是检索与原文阅读，不生成模型回答。源码开发版没有签名公证安装包。','Real automatic transcription and automated model memory organization are still in development. Real-model quality, remote cloud storage and background workflows still need real-world validation. Source conversation currently retrieves and reads originals, not generated model answers. There is no signed and notarized installer.'))}</div></section>'''
    return hero+capture+schedule+sources+tools+memory+ownership+ending
